const t = input.split(/\s+/).filter(Boolean)
const n = Number(t[0])
const text = t.slice(1, 1 + n)
let p = 1 + n
const q = Number(t[p++])
const queries = []
for (let i = 0; i < q; i++) {
  const m = Number(t[p])
  const k = Number(t[p + 1])
  queries.push({ k, words: t.slice(p + 2, p + 2 + m) })
  p += 2 + m
}
const res = findStarts(text, queries)
console.log(res.map(r => (r.length ? r.join(' ') : '-1')).join('\n'))

