int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> text(n);
    for (int i = 0; i < n; i++) cin >> text[i];
    int q;
    cin >> q;
    vector<pair<int, vector<string>>> queries(q);
    for (int i = 0; i < q; i++) {
        int m, k;
        cin >> m >> k;
        queries[i].first = k;
        queries[i].second.resize(m);
        for (int j = 0; j < m; j++) cin >> queries[i].second[j];
    }
    vector<vector<int>> res = findStarts(text, queries);
    for (auto& r : res) {
        if (r.empty()) cout << -1;
        for (size_t i = 0; i < r.size(); i++) cout << r[i] << (i + 1 < r.size() ? " " : "");
        cout << '\n';
    }
    return 0;
}

