import java.util.*;
import java.io.*;

public class Main {
    static List<List<Integer>> findStarts(List<String> text, List<Integer> ks, List<List<String>> queryWords) {
        // Write your solution here
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < ks.size(); i++) res.add(new ArrayList<>());
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        List<String> text = new ArrayList<>();
        for (int i = 0; i < n; i++) text.add(st.nextToken());
        int q = Integer.parseInt(st.nextToken());
        List<Integer> ks = new ArrayList<>();
        List<List<String>> queryWords = new ArrayList<>();
        for (int i = 0; i < q; i++) {
            int m = Integer.parseInt(st.nextToken());
            ks.add(Integer.parseInt(st.nextToken()));
            List<String> ws = new ArrayList<>();
            for (int j = 0; j < m; j++) ws.add(st.nextToken());
            queryWords.add(ws);
        }
        List<List<Integer>> res = findStarts(text, ks, queryWords);
        StringBuilder sb = new StringBuilder();
        for (List<Integer> r : res) {
            if (r.isEmpty()) sb.append(-1);
            for (int i = 0; i < r.size(); i++) sb.append(r.get(i)).append(i + 1 < r.size() ? " " : "");
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
